import sys, os
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from _b import *

p = Pack("fslc-social-studies", "Social Studies — FSLC", level="Class 6", subject="histoire-geo", cursus="primary", exam="FSLC",
         description="Key-point lessons, worked examples, FSLC-style exercises with answers and a mock paper: Cameroon geography, simple history of Cameroon, civic education, Africa and the world, and map skills.",
         programRef="MINEDUB primary school curriculum (English-speaking subsystem), Level III — Social Studies (geography, history, citizenship); to be checked against the official texts",
         wanted="social-studies")
REF = p.programRef
SENS = "Facts about Cameroon are limited to well-established, neutral points; dates and names to be checked by a teacher against the official textbook."

# =========================================================== chapter 1: geography of Cameroon
ch = p.chapter("geography", "Geography of Cameroon", REF)
regions = [("Adamawa", "Ngaoundéré"), ("Centre", "Yaoundé"), ("East", "Bertoua"), ("Far North", "Maroua"), ("Littoral", "Douala"),
           ("North", "Garoua"), ("North-West", "Bamenda"), ("West", "Bafoussam"), ("South", "Ebolowa"), ("South-West", "Buea")]
assert len(regions) == 10
fig_reg = shapes([x for i, (r, c) in enumerate(regions) for x in (
    RECT(8 + (i % 2) * 196, 8 + (i // 2) * 40, 188, 34, fill=("lightblue", "lightyellow", "lightgreen")[i % 3], radius=5),
    T(102 + (i % 2) * 196, 31 + (i // 2) * 40, r + ": " + c, 13, bold=True))], 400, 214)
build(ch, "location-regions", "Where is Cameroon? Regions and regional capitals", 30,
    ["Say where Cameroon is and name its neighbours.", "Name the ten regions of Cameroon and their capitals.", "Name the capital city and the two official languages."],
    [("key", "definition", "Location", "Cameroon is in **Central Africa**, just north of the **Equator**. It has a coast on the **Atlantic Ocean** (the Gulf of Guinea). Its neighbours are **Nigeria** (west), **Chad** (north-east), the **Central African Republic** (east), the **Republic of the Congo**, **Gabon** and **Equatorial Guinea** (south). The area is about 475,000 square kilometres."),
     ("key", "definition", "Capital and languages", "The political capital is **Yaoundé**. **Douala** is the biggest city and the main port. The two official languages are **English** and **French**, and there are also many national languages. Cameroon is often called **Africa in miniature** because it has forests, mountains, savanna, a coast and a desert edge."),
     ("fig", fig_reg, "The ten regions of Cameroon and their capitals.", "Ten boxes. Each shows a region and its capital: Adamawa, Ngaoundéré; Centre, Yaoundé; East, Bertoua; Far North, Maroua; Littoral, Douala; North, Garoua; North-West, Bamenda; West, Bafoussam; South, Ebolowa; South-West, Buea."),
     ("key", "retenir", "Remembering the regions", "There are **10 regions**. Three are in the **north** (Far North, North, Adamawa). Two are **English-speaking** regions in the west (North-West and South-West). The others are Centre, East, Littoral, South and West. Learn them with the capitals in pairs: Littoral-Douala, West-Bafoussam, South-West-Buea."),
     ("key", "pieges", "Common mistakes", "- Mixing up the **capital of Cameroon** (Yaoundé) and the **biggest city** (Douala).\n- Confusing a region with its capital (the Littoral is the region; Douala is its capital).\n- Writing *North West* and *Northwest* in different ways: use *North-West* and *South-West*.\n- Saying that Cameroon is in West Africa only."),
     ("ex", "Example 1", "Give the capital of the South-West Region and the capital of the Far North Region.", ["South-West: the regional capital is Buea.", "Far North: the regional capital is Maroua."], "Buea and Maroua."),
     ("ex", "Example 2", "Name three neighbours of Cameroon and say in which direction each one lies.", ["Nigeria is to the west.", "Chad is to the north-east, and Gabon is to the south."], "Nigeria (west), Chad (north-east), Gabon (south).")],
    [M("application", "What is the capital of the West Region?", "Bafoussam", ["Bamenda", "Bertoua", "Buea"], "Bafoussam is the capital of the West Region."),
     N("application", "How many regions does Cameroon have?", len(regions), "There are ten regions."),
     M("application", "Which country is a neighbour of Cameroon to the west?", "Nigeria", ["Gabon", "Chad", "Equatorial Guinea"], "Nigeria is on the west side."),
     MA("approfondissement", "Match the region with its capital.", [("Littoral", "Douala"), ("North-West", "Bamenda"), ("East", "Bertoua"), ("South", "Ebolowa")], "Learn the regions and capitals in pairs."),
     TF("approfondissement", "Douala is the political capital of Cameroon.", False, "Yaoundé is the political capital. Douala is the biggest city and main port."),
     P("A teacher shows pupils the regions on a map. Eko lives in Buea, Ada lives in Maroua and Neba lives in Bamenda.",
       [PM("In which region does Eko live?", "South-West", ["North-West", "Littoral", "West"], "Buea is the capital of the South-West Region."),
        PM("In which region does Ada live?", "Far North", ["North", "Adamawa", "East"], "Maroua is the capital of the Far North Region."),
        PM("Which two regions are English-speaking?", "North-West and South-West", ["West and Littoral", "East and South", "North and Far North"], "Bamenda and Buea are the capitals of the two English-speaking regions.", points=2)])],
    [("The political capital of Cameroon is...", "Yaoundé", ["Douala", "Garoua", "Limbe"], "Yaoundé is the capital."),
     ("Cameroon is on the coast of the...", "Atlantic Ocean", ["Indian Ocean", "Pacific Ocean", "Red Sea"], "Cameroon is on the Gulf of Guinea."),
     ("What is the capital of the North Region?", "Garoua", ["Maroua", "Ngaoundéré", "Bertoua"], "Garoua is the capital of the North."),
     ("The two official languages are...", "English and French", ["English and Spanish", "French and Arabic", "Fulfulde and Ewondo"], "English and French are the official languages."),
     ("Cameroon is called 'Africa in miniature' because it has...", "many kinds of landscapes and climates", ["only forests", "only deserts", "no mountains"], "It has coast, forest, mountains and savanna.")],
    [SENS, "Area (about 475,000 km²) and regional capitals are standard facts; check against the textbook. 'Africa in miniature' is a common nickname."],
    prereq=[])

fig_relief = shapes([POLY([20, 190, 90, 190, 110, 150, 150, 150, 170, 110, 210, 110, 230, 75, 250, 40, 270, 75, 295, 110, 330, 110, 380, 190], fill="lightgreen", closed=True),
                     T(60, 215, "coast", 13, bold=True), T(250, 25, "Mount Cameroon area", 12), T(190, 215, "plateaus and highlands", 13, bold=True), T(335, 215, "northern plains", 13, bold=True)], 400, 235)
build(ch, "relief-rivers", "Relief, rivers and lakes of Cameroon", 30,
    ["Describe the main relief regions: coastal plain, plateaus, highlands, northern plains.", "Name Mount Cameroon, the main rivers and two lakes.", "Say why rivers and mountains are useful."],
    [("key", "definition", "Relief", "**Relief** means the shape of the land. Cameroon has: the low **coastal plain** on the Atlantic; the **Southern plateau** (the forest zone); the **Western highlands** (the Grassfields, with high hills and volcanic mountains); the **Adamawa plateau** in the centre; and the flat **northern plains** towards Lake Chad and the River Benue."),
     ("fig", fig_relief, "A simple profile of the land from the coast to the north.", "A green hill-shaped profile. The land is low at the coast, rises to a highest peak near Mount Cameroon, falls over plateaus and highlands, and is low again in the northern plains."),
     ("key", "retenir", "Mount Cameroon", "**Mount Cameroon** (also called **Fako**) is the highest mountain in Cameroon, about 4,000 metres high. It is an **active volcano** near Buea and Limbe, in the South-West Region. People climb it for sport, and farmers use the fertile volcanic soil around it."),
     ("key", "retenir", "Rivers and lakes", "Important rivers: the **Sanaga** (the longest river wholly in Cameroon), the **Wouri** (flows into the sea near Douala), the **Benue** (flows north-west to Nigeria) and the **Logone** (flows toward Lake Chad). **Lake Chad** is in the far north and is shared with other countries. **Lake Nyos** is a small crater lake in the North-West. Rivers give water, fish, transport and **hydroelectric power**."),
     ("key", "pieges", "Common mistakes", "- Saying that Mount Cameroon is in the North or in the West: it is in the **South-West**.\n- Thinking that all rivers flow to the same sea: some flow to the Atlantic, some to the Niger and some to Lake Chad.\n- Mixing up **relief** (shape of the land) with **climate** (weather)."),
     ("ex", "Example 1", "In which region is Mount Cameroon, and what kind of mountain is it?", ["Mount Cameroon stands near Buea and Limbe.", "Buea and Limbe are in the South-West Region, and the mountain is an active volcano."], "In the South-West Region; it is an active volcano."),
     ("ex", "Example 2", "Give two uses of a river such as the Sanaga.", ["People use river water for farming and fishing.", "Dams on the Sanaga produce electricity, and rivers can also carry boats."], "Fishing and electricity (also water for farming, transport).")],
    [M("application", "What is the highest mountain in Cameroon?", "Mount Cameroon", ["Mount Kilimanjaro", "Mount Oku", "Mount Manengouba"], "Mount Cameroon (Fako) is the highest in Cameroon."),
     M("application", "Which river flows into the sea near Douala?", "the Wouri", ["the Benue", "the Logone", "the Nile"], "The Wouri estuary is at Douala."),
     M("application", "Which lake is in the far north of Cameroon?", "Lake Chad", ["Lake Nyos", "Lake Victoria", "Lake Malawi"], "Lake Chad is in the far north."),
     TF("approfondissement", "The coastal plain of Cameroon is low land.", True, "It is low land next to the Atlantic Ocean."),
     MA("approfondissement", "Match the feature with its place.", [("Mount Cameroon", "South-West Region"), ("Lake Chad", "far north"), ("River Wouri", "near Douala"), ("Adamawa plateau", "centre of Cameroon")], "These are well-known features."),
     P("A group of pupils from Bamenda plans a school trip. They want to see a volcano, a big river port and a lake.",
       [PM("Which mountain can they visit near Buea?", "Mount Cameroon", ["Mount Oku", "Mount Kilimanjaro", "Mount Kenya"], "Mount Cameroon is an active volcano near Buea."),
        PM("Which river is near the big port city of Douala?", "the Wouri", ["the Benue", "the Logone", "the Sanaga's source"], "The Wouri river meets the sea at Douala."),
        PM("Which feature is a lake?", "Lake Nyos", ["Mount Cameroon", "the Sanaga", "the Wouri"], "Lake Nyos is a crater lake.", points=2)])],
    [("Relief means...", "the shape of the land", ["the weather", "the people", "the farming"], "Hills, plains and mountains."),
     ("The Sanaga is...", "a river", ["a lake", "a mountain", "a town"], "It is the longest river wholly in Cameroon."),
     ("Mount Cameroon is a...", "volcano", ["lake", "desert", "plain"], "It is an active volcano."),
     ("Which region has the coast and Mount Cameroon?", "South-West", ["North", "East", "Adamawa"], "Buea and Limbe are in the South-West."),
     ("A use of rivers is...", "producing electricity", ["making clouds", "making soil", "growing mountains"], "Dams on rivers produce electricity.")],
    [SENS, "Height of Mount Cameroon is given as 'about 4,000 m' because books give slightly different figures (e.g. 4,040 m).", "Relief profile is schematic, not a real map."],
    prereq=["fslc-social-studies-location-regions"])

fig_clim = shapes([RECT(60, 20, 280, 40, fill="lightyellow"), T(200, 46, "North: Sahel and savanna, one rainy season", 13, bold=True),
                   RECT(60, 70, 280, 40, fill="lightgreen"), T(200, 96, "Centre: savanna and highlands", 13, bold=True),
                   RECT(60, 120, 280, 40, fill="green"), T(200, 146, "South: rainforest, two rainy seasons", 13, bold=True, color="white"),
                   LINE(35, 25, 35, 155, arrow="end", width=3), T(20, 90, "wetter", 11, anchor="end")], 400, 185)
build(ch, "climate-vegetation", "Climate and vegetation of Cameroon", 30,
    ["Describe the two main climates of Cameroon and the seasons.", "Name the vegetation zones and some plants and animals of each.", "Explain why the north is drier than the south."],
    [("key", "definition", "Climate", "**Climate** is the usual weather of a place over many years. The **south** of Cameroon has a **hot, wet equatorial climate** with **two rainy seasons and two dry seasons**. The **north** is **hotter and drier** with **one rainy season** (about May to October) and a long dry season. The **highlands** are cooler. Weather also changes with height: it is cooler on mountains."),
     ("fig", fig_clim, "Rainfall gets less from the south to the north.", "Three bands. The northern band says Sahel and savanna with one rainy season. The middle band says savanna and highlands. The southern band says rainforest with two rainy seasons. An arrow points to the south for wetter."),
     ("key", "retenir", "Vegetation zones", "- **Equatorial rainforest** (south and east): tall trees, thick leaves, many animals (monkeys, elephants, gorillas in reserves). Korup and Dja are forest reserves.\n- **Savanna** (centre, Adamawa, Grassfields): grass with scattered trees.\n- **Sahel / dry savanna** (far north): short grass, thorny trees; Waza National Park protects lions and elephants.\n- **Mangroves** grow along the coast."),
     ("key", "retenir", "Harmattan", "In the dry season a dry, dusty wind called the **Harmattan** blows from the Sahara. It makes the air dusty and cool at night, and lips and skin dry. Wearing warm clothes at night and drinking water helps. People in the north feel it most."),
     ("key", "pieges", "Common mistakes", "- Saying that the whole country has the same climate.\n- Thinking that rainforest means it is raining all day: it has dry months too.\n- Mixing **weather** (today) and **climate** (over many years).\n- Forgetting that the highlands (West, North-West) are cooler than the lowlands."),
     ("ex", "Example 1", "Why does the south grow cocoa and the north grow cotton?", ["Cocoa needs a lot of rain and heat: the south is wet.", "Cotton needs a long sunny dry season: the north has one rainy season and a long dry one."], "Cocoa likes the wet, warm south; cotton likes the drier north."),
     ("ex", "Example 2", "Name two differences between the climate of Douala and of Maroua.", ["Douala is on the coast: hot, very wet, with two rainy seasons.", "Maroua is in the far north: hot, much drier, with one short rainy season."], "Douala is wetter with two rainy seasons; Maroua is drier with one.")],
    [M("application", "Which climate does the south of Cameroon have?", "hot and wet (equatorial)", ["cold and dry", "hot desert", "cold and wet"], "The south is hot and wet."),
     M("application", "How many rainy seasons does the far north have?", "one", ["two", "three", "none"], "The north has one rainy season."),
     M("application", "Which vegetation grows in the south of Cameroon?", "rainforest", ["Sahel", "desert", "snow"], "The south has tropical rainforest."),
     TF("approfondissement", "The Harmattan is a dry, dusty wind from the Sahara.", True, "It blows in the dry season."),
     MA("approfondissement", "Match the zone with an example.", [("rainforest", "Korup"), ("savanna", "the Grassfields"), ("Sahel", "the far north"), ("mangroves", "the coast")], "These are standard examples."),
     P("Mary's family lives in Bafoussam in the West Region. Her cousin lives in Maroua. Mary says: 'It is cooler here in the highlands than where my cousin lives.'",
       [PM("Is Mary right?", "Yes, highlands are cooler", ["No, the highlands are hotter", "No, it is exactly the same", "Only in the rainy season"], "Height makes places cooler."),
        PM("Which place is drier?", "Maroua", ["Bafoussam", "both are equal", "neither"], "The far north is drier."),
        PM("Which crop is likely to be grown near Maroua?", "cotton", ["cocoa", "oil palm", "rubber"], "Cotton likes the drier north.", points=2)])],
    [("The wet season in the north lasts about...", "May to October", ["all year", "January only", "December to February"], "The north has one long dry season."),
     ("The Harmattan is a...", "dry dusty wind", ["cold rain", "type of fruit", "mountain"], "It comes from the Sahara."),
     ("Which zone is wettest?", "the rainforest in the south", ["the Sahel", "the highlands only", "Lake Chad"], "The south is wettest."),
     ("Waza National Park is in the...", "Far North", ["South-West", "East", "Centre"], "It protects savanna animals."),
     ("It is cooler in the highlands because...", "they are high above sea level", ["they are near the Equator only", "they are in the north", "they have no rain"], "Temperature falls with height.")],
    [SENS, "Exact months of the seasons vary by region and year: given loosely. Reserves named (Korup, Dja, Waza) are well known; wildlife examples simplified."],
    prereq=["fslc-social-studies-relief-rivers"])

fig_eco = grid([("Primary", "farming, fishing, mining"), ("Secondary", "factories, processing"), ("Tertiary", "trade, transport, schools")], 3, 120, 70, gap=8, size=12)
build(ch, "economy-transport", "Economic activities and transport", 35,
    ["Name the main economic activities and the regions where they are important.", "Tell primary, secondary and tertiary activities apart.", "Name the main means of transport and a few ports, railways and airports."],
    [("key", "definition", "Economic activities", "People work to earn money and to produce what we need. **Primary** activities take things from nature: farming, fishing, herding, forestry and mining. **Secondary** activities change them into other goods: factories, food processing, sawmills. **Tertiary** activities are services: trade, transport, banks, teaching, health care and tourism."),
     ("fig", fig_eco, "Primary, secondary and tertiary activities.", "Three boxes: primary (farming, fishing, mining), secondary (factories, processing) and tertiary (trade, transport, schools)."),
     ("key", "retenir", "Farming and other activities", "- **Cash crops**: cocoa (Centre, South, South-West), coffee (West, South-West, Littoral), cotton (North), bananas, oil palm, rubber and tea.\n- **Food crops**: cassava, plantain, maize, yams, groundnuts, beans.\n- **Livestock**: cattle in the Adamawa, North and North-West.\n- **Fishing** on the coast, rivers and Lake Chad.\n- **Timber** from the forests of the East and South.\n- **Petroleum** from the sea near the coast; **tourism** and **trade**."),
     ("key", "retenir", "Transport", "Cameroon uses **roads** (the most used), **railways** (Douala-Yaoundé and Yaoundé-Ngaoundéré), **rivers and the sea** (the ports of **Douala** and **Kribi**), and **air** (international airports at Douala and Yaoundé, and others). Good transport helps farmers to sell their crops and brings goods to the towns. Neighbouring countries such as Chad and the Central African Republic also use Cameroon's roads, railway and port."),
     ("key", "pieges", "Common mistakes", "- Placing cocoa in the dry north or cotton in the rainforest.\n- Calling a factory a primary activity: it is **secondary**.\n- Thinking that only farming is work: teaching, driving and trading are also important activities.\n- Forgetting that food processing (making oil from palm nuts) adds value to crops."),
     ("ex", "Example 1", "Classify as primary, secondary or tertiary: (a) growing cocoa, (b) making chocolate in a factory, (c) selling chocolate in a shop.", ["(a) Growing cocoa takes a product from the land: primary.", "(b) Making chocolate changes cocoa into a new product: secondary.", "(c) Selling is a service: tertiary."], "(a) primary; (b) secondary; (c) tertiary."),
     ("ex", "Example 2", "Why are roads important for farmers in the West Region?", ["Farmers need to carry maize, vegetables and coffee to markets in towns.", "Good roads make the journey faster and the goods stay fresh."], "They carry crops to markets quickly and cheaply, so farmers earn more.")],
    [M("application", "Which is a cash crop grown mainly in the north of Cameroon?", "cotton", ["cocoa", "oil palm", "rubber"], "Cotton likes the drier north."),
     M("application", "Fishing and farming are...", "primary activities", ["secondary activities", "tertiary activities", "not work"], "They take products from nature."),
     M("application", "Which is the biggest port of Cameroon?", "Douala", ["Garoua", "Bamenda", "Maroua"], "Douala is the main port."),
     TF("approfondissement", "A teacher is working in a tertiary activity.", True, "Teaching is a service."),
     MA("approfondissement", "Match the activity with its type.", [("growing maize", "takes a product from the land"), ("making palm oil in a factory", "changes raw materials into goods"), ("driving a taxi", "gives a service"), ("fishing", "takes a product from the water")], "Think about what the person does with the product."),
     P("A farmer in the Centre Region grows cocoa. A company buys the cocoa, dries it and makes cocoa butter in a factory in Douala. Shops sell chocolate to people.",
       [PM("Which activity is primary?", "growing the cocoa", ["making cocoa butter", "selling chocolate", "driving a lorry only"], "Growing takes a product from the land."),
        PM("Which activity is secondary?", "making cocoa butter in a factory", ["growing cocoa", "selling chocolate", "going to school"], "A factory changes raw materials into products."),
        PM("Which service helps the cocoa reach Douala?", "transport", ["farming", "mining", "forestry"], "Lorries and roads carry the cocoa.", points=2)])],
    [("Cattle are mainly reared in...", "Adamawa and the North", ["the coast", "the cities only", "the sea"], "Open grassland suits cattle."),
     ("A factory that makes biscuits is a...", "secondary activity", ["primary activity", "tertiary activity", "farm"], "It changes raw materials into goods."),
     ("Which crop is a food crop?", "cassava", ["cotton", "rubber", "cocoa"], "Cassava is eaten by families."),
     ("Which is a means of air transport?", "aeroplane", ["lorry", "canoe", "train"], "Planes fly."),
     ("Timber is mainly obtained from...", "forests", ["deserts", "lakes", "mountains of ice"], "Trees grow in forests.")],
    [SENS, "Regions named for each crop are simplified (several crops grow in several regions). Port of Kribi and railway lines are well known but their details (dates, capacity) are not given.", "Petroleum is mentioned in general terms only; no production figures."],
    prereq=["fslc-social-studies-climate-vegetation"])

# =========================================================== chapter 2: history
ch = p.chapter("history", "A simple history of Cameroon", REF)
assert 1916 - 1884 == 32 and 1972 - 1960 == 12 and 1961 - 1960 == 1 and 1884 - 1472 == 412
fig_t1 = timeline(1450, 1930, [(1472, "Portuguese on the coast"), (1884, "German protectorate"), (1916, "Britain and France")], [], 480, 230)
build(ch, "history-early-colonial", "From early times to colonial rule", 35,
    ["Say who the first peoples and kingdoms of Cameroon were and how Cameroon got its name.", "Describe the German period and the division between Britain and France.", "Put the main events in order on a timeline."],
    [("key", "definition", "Early times and the name Cameroon", "Many peoples have lived in the land of Cameroon for a very long time, for example forest peoples such as the Baka, farming peoples and the peoples of the Grassfields, with kingdoms and chiefdoms such as the **Bamum** in the West and the **Duala** chiefs on the coast. In about **1472** Portuguese sailors arrived at the River Wouri and called it the *river of prawns* (*Rio dos Camarões*). The name **Cameroon** comes from this."),
     ("fig", fig_t1, "Three important dates before independence.", "A timeline from 1450 to 1930 with three events: Portuguese arrive about 1472, German protectorate 1884, Britain and France take over in 1916."),
     ("key", "retenir", "German rule", "In **1884** the Duala chiefs signed treaties with Germany, and the country became a German **protectorate** called *Kamerun*. The Germans built roads, railways and plantations. Many Cameroonians were made to work for them, and some people resisted. German rule lasted until the First World War."),
     ("key", "retenir", "Britain and France", "In the First World War, British and French forces took Kamerun. By **1916** the Germans had left. The country was **divided** between **Britain** (a smaller part in the west, the British Cameroons) and **France** (a larger part, French Cameroun). The League of Nations gave them **mandates** to rule, and after 1945 the United Nations gave them **trusteeship**. This is why Cameroon has two official languages today."),
     ("key", "pieges", "Common mistakes", "- Saying that Cameroon was always one country: it was divided in 1916.\n- Mixing up the dates: 1472 (Portuguese), 1884 (German protectorate), 1916 (Britain and France).\n- Thinking that the Portuguese ruled Cameroon: they only traded on the coast.\n- Giving opinions as facts; in history we use sources and dates."),
     ("ex", "Example 1", "How did Cameroon get its name?", ["About 1472 Portuguese sailors reached the River Wouri.", "They found many prawns and named it the river of prawns, Rio dos Camarões. Later the name became Cameroon."], "From Rio dos Camarões, the Portuguese name for the River Wouri (the river of prawns)."),
     ("ex", "Example 2", "How many years passed between the German treaties (1884) and the division between Britain and France (1916)?", ["Subtract the dates: 1916 − 1884.", "1916 − 1884 = 32."], "32 years.")],
    [M("application", "Which European country made Cameroon a protectorate in 1884?", "Germany", ["Britain", "France", "Portugal"], "Germany signed treaties with the Duala chiefs in 1884."),
     M("application", "What does 'Rio dos Camarões' mean?", "river of prawns", ["river of gold", "river of fish and boats", "red river"], "Camarões means prawns."),
     N("application", "How many years are there between 1884 and 1916?", 1916 - 1884, "1916 − 1884 = 32."),
     TF("approfondissement", "After 1916 the whole of Cameroon was ruled only by France.", False, "It was divided between Britain (smaller part) and France (larger part)."),
     MA("approfondissement", "Match the date with the event.", [("about 1472", "Portuguese sailors reach the Wouri"), ("1884", "German protectorate begins"), ("1916", "Germans leave; Britain and France divide the land"), ("1945 onwards", "United Nations trusteeship")], "These are the main events in order."),
     P("Read: In 1884 the Duala chiefs and Germany signed treaties. German rule built a railway and plantations. In 1916, after the First World War, Britain and France divided Cameroon.",
       [PM("Which country ruled Cameroon first, after the Portuguese traders?", "Germany", ["Britain", "France", "Nigeria"], "Germany ruled from 1884."),
        PM("In what year did Britain and France divide Cameroon?", "1916", ["1884", "1960", "1472"], "After the First World War, in 1916."),
        PM("Which is a reason why Cameroon has two official languages?", "it was ruled by Britain and France", ["the Portuguese taught English", "the Bamum brought French", "there is no reason"], "British and French rule left English and French.", points=2)])],
    [("The Portuguese reached the Wouri in about...", "1472", ["1884", "1916", "1960"], "That is the date usually given."),
     ("A protectorate is...", "a country controlled by a stronger country", ["a free country", "a kind of school", "a forest"], "The protecting power controls the land."),
     ("The name Cameroon comes from the Portuguese word for...", "prawns", ["mountains", "chiefs", "forest"], "Camarões = prawns."),
     ("Who ruled the larger part of Cameroon after 1916?", "France", ["Germany", "Portugal", "Nigeria"], "French Cameroun was the larger part."),
     ("The Bamum kingdom is in the...", "West", ["Far North", "East", "South-West"], "Bamum is in the West Region (Foumban).")],
    [SENS, "Dates (1472, 1884, 1916) are those commonly given in school textbooks; 1472 is approximate. Mention of resistance and forced labour is deliberately brief; textbook wording to be checked.", "The slave trade era is not covered."],
    prereq=["fslc-social-studies-location-regions"])

