# =========================================================== chapter 3: civic education
ch = p.chapter("civics", "Civic education", REF)
fig_rd = grid([("Rights", "what you may have"), ("Duties", "what you must do")], 2, 170, 70, gap=20, size=15)
build(ch, "rights-duties", "Rights and duties of the child and the citizen", 30,
    ["Name important rights of children and the duties that go with them.", "Explain that every right brings a responsibility.", "Give examples of good behaviour at school and at home."],
    [("key", "definition", "Rights and duties", "A **right** is something that every person should have or may do. A **duty** is something we must do. Rights and duties go together: if I have a right, I must respect the same right of others. Children's rights are protected by the **Convention on the Rights of the Child** of the United Nations."),
     ("fig", fig_rd, "Rights and duties go together.", "Two boxes side by side. The first says Rights: what you may have. The second says Duties: what you must do."),
     ("key", "retenir", "Rights of the child", "Children have the right to: **life** and a **name**; **education**; **health care**; **food, clean water and a home**; **protection** from harm and from work that damages their health or school; **rest and play**; to be **heard** and to **practise their religion**; and to be treated **equally** whatever their sex, tribe or religion."),
     ("key", "retenir", "Duties of a pupil and a citizen", "A pupil must: **respect** teachers, parents and other pupils; **obey** school rules; come **on time**; do homework; **look after** school property and keep the school clean. A citizen must: **obey the laws**, **respect** others and their property, **pay taxes** (adults), protect public property, and help to keep the community safe and clean."),
     ("key", "pieges", "Common mistakes", "- Thinking that rights mean we can do anything we like: my rights end where the rights of others begin.\n- Thinking that only adults have rights.\n- Forgetting that children also have duties.\n- Breaking public property (a desk, a tap, a road sign): it belongs to everybody."),
     ("ex", "Example 1", "Right or duty? (a) Going to school. (b) Obeying the school rules.", ["(a) Every child has the right to education.", "(b) Obeying the rules is a duty of every pupil."], "(a) a right; (b) a duty."),
     ("ex", "Example 2", "A pupil writes on the desk with a pen. Which duty is broken, and what should he do?", ["The duty to look after school property.", "He should say sorry, clean the desk and not do it again."], "He broke the duty to look after school property; he should say sorry and clean the desk.")],
    [M("application", "Which is a right of every child?", "education", ["to break the rules", "to hit other children", "to come late"], "Education is a right."),
     M("application", "Which is a duty of a pupil?", "to obey the school rules", ["to eat in class", "to shout at teachers", "to leave early"], "Obeying rules is a duty."),
     M("application", "Who should keep the school clean?", "everybody", ["only the teacher", "only the cleaner", "nobody"], "Every pupil has a duty to help."),
     TF("approfondissement", "Because I have rights, I can do anything I want.", False, "My rights end where the rights of others begin."),
     MA("approfondissement", "Match the right with an example.", [("right to health care", "going to the clinic when sick"), ("right to education", "going to school"), ("right to play", "playing in the break"), ("right to a name", "having a birth certificate")], "Each right has a practical example."),
     P("Ako sees some pupils throwing stones at a school window and a child who wants to play football being sent away because he is 'too small'.",
       [PM("Which duty are the pupils who throw stones forgetting?", "to respect school property", ["to pay taxes", "to vote", "to travel"], "A window belongs to the school."),
        PM("Which right is the small child denied?", "the right to play and to be treated equally", ["the right to vote", "the right to drive", "the right to work"], "All children have the right to play."),
        PM("What should Ako do?", "tell a teacher politely and set a good example", ["throw stones too", "laugh and walk away", "break another window"], "Responsible pupils help the community.", points=2)])],
    [("A right is something that...", "everyone should have", ["nobody should have", "only adults have", "is a punishment"], "Rights belong to everyone."),
     ("Which is a duty?", "respecting others", ["breaking rules", "wasting water", "hurting animals"], "Respect is a duty."),
     ("Children's rights are protected by...", "the Convention on the Rights of the Child", ["a school rule only", "a football law", "nothing"], "It was adopted by the United Nations."),
     ("Public property is...", "owned by everybody", ["owned by nobody", "owned by one pupil", "free to destroy"], "We must look after it."),
     ("Every right is linked to a...", "responsibility", ["holiday", "colour", "price"], "Rights and duties go together.")],
    [SENS, "Child rights are listed in simplified form from the UN Convention; check that they match the wording of the official civic education syllabus. Mention of taxes applies to adults only."],
    prereq=[])

