     M("application", "Which is the longest river in Africa?", "the Nile", ["the Wouri", "the Sanaga", "the Benue"], "The Nile is the longest river in Africa."),
     TF("approfondissement", "Africa is a country.", False, "Africa is a continent with about 54 countries."),
     MA("approfondissement", "Match the feature with its type.", [("Sahara", "desert"), ("Kilimanjaro", "mountain"), ("Victoria", "lake"), ("Atlantic", "ocean")], "Each is a physical feature."),
