L = build(ch, "map-skills", "Map skills: direction, symbols, scale and grid references", 35,
    ["Use the eight points of the compass.", "Read a map key (symbols) and a simple scale.", "Give and read a grid reference."],
    [("key", "definition", "Compass directions", "The four main directions are **North, East, South and West**. Between them are North-East (NE), South-East (SE), South-West (SW) and North-West (NW). On most maps **North is at the top**. A **compass** shows the direction: its needle points to the north. To remember the order, say: **N**ever **E**at **S**oggy **W**affles (clockwise)."),
     ("fig", fig_comp, "The eight points of the compass.", "A compass rose with eight arms. The labels are N at the top, E at the right, S at the bottom, W at the left, and NE, SE, SW, NW between them."),
     ("key", "retenir", "Map key and scale", "A **map key** (legend) explains the **symbols** on a map: a blue line for a river, a black line for a road, a dot for a town. The **scale** tells how real distances are shown on the map. If the scale is **1 cm to 20 km**, then 1 cm on the map is 20 km on the ground. To find the real distance: **measure on the map, then multiply** by the scale."),
     ("key", "methode", "Grid references", "A grid map is divided into squares. The columns have **letters** (A, B, C, D) and the rows have **numbers** (1, 2, 3, 4). To give a **grid reference**, say the **letter first and then the number**: B2. A **physical map** shows relief and water; a **political map** shows countries, regions and towns; latitudes run east-west and longitudes north-south."),
     ("key", "pieges", "Common mistakes", "- Forgetting that north is at the **top** of a map.\n- Multiplying by the wrong number, or forgetting to use the scale.\n- Giving the number before the letter in a grid reference.\n- Measuring a distance from the edge of the ruler instead of from the 0 mark."),
     ("ex", "Example 1", "On a map with a scale of 1 cm to 20 km, two towns are 4.5 cm apart. What is the real distance?", ["Each centimetre stands for 20 km.", "4.5 × 20 = 90 km."], "90 km."),
     ("ex", "Example 2", "In the grid picture, in which square is the school?", ["The school is in the second column (B) and the second row.", "The reference is B2."], "B2.", fig_gridmap)],
    [M("application", "Which direction is opposite to north-east?", "south-west", ["north-west", "south-east", "east"], "NE and SW are opposite."),
     N("application", "Scale: 1 cm to 20 km. Two towns are 4.5 cm apart on the map. How far apart are they (km)?", 90, "4.5 × 20 = 90 km.", unit="km"),
     M("application", "On a map, what does the map key explain?", "the symbols", ["the age of the map", "the colour of the paper", "the name of the artist"], "The key shows what each symbol means."),
     N("approfondissement", "Scale: 1 cm to 20 km. The real distance between two villages is 150 km. How many cm apart are they on the map?", 7.5, "150 ÷ 20 = 7.5 cm.", tol=0.01, unit="cm"),
     TF("approfondissement", "In a grid reference we write the number first and then the letter.", False, "The letter comes first: B2, not 2B."),
     P("A map has the scale 1 cm to 5 km. The distance from Ada's village to the market is 6 cm on the map, and the school is 2 cm north of the village.",
       [PN("What is the real distance from the village to the market?", 30, "6 × 5 = 30 km.", unit="km", points=2),
        PN("What is the real distance from the village to the school?", 10, "2 × 5 = 10 km.", unit="km"),
        PM("In which direction is the school from the village?", "north", ["south", "east", "west"], "North is at the top of the map.", points=1)])],
    [("North is usually shown at the...", "top of the map", ["bottom of the map", "left of the map", "right of the map"], "North is at the top."),
     ("The scale 1 cm to 10 km means 3 cm on the map is...", "30 km", ["13 km", "3 km", "300 km"], "3 × 10 = 30."),
     ("In the grid reference C3 the letter C shows the...", "column", ["row", "scale", "key"], "Letters are for columns."),
     ("A compass needle points to the...", "north", ["south", "east", "west"], "Magnetic north."),
     ("A blue line on a map usually shows a...", "river", ["road", "border", "railway"], "Check the key to be sure.")],
    [SENS, "Mnemonic 'Never Eat Soggy Waffles' is a common memory aid, not a fact; the teacher may replace it. A blue line = river is the usual convention; check the map key each time."],
    prereq=["fslc-social-studies-africa-world"])

# =========================================================== mock paper (20 marks)
LM = L
a = [add(LM, M("application", q, r, w, e), True) for q, r, w, e in [
    ("What is the capital of the North-West Region?", "Bamenda", ["Buea", "Bafoussam", "Bertoua"], "Bamenda is the capital of the North-West."),
    ("Which mountain is an active volcano in the South-West Region?", "Mount Cameroon", ["Mount Oku", "Kilimanjaro", "Mount Kenya"], "Mount Cameroon (Fako)."),
    ("Which vegetation grows in the south of Cameroon?", "rainforest", ["Sahel", "desert", "snow"], "The south is hot and wet."),
    ("Which is the main port of Cameroon?", "Douala", ["Maroua", "Garoua", "Bafoussam"], "Douala is on the Wouri estuary.")]]
a.append(add(LM, MA("application", "Match the region with its capital.", [("Littoral", "Douala"), ("North", "Garoua"), ("South", "Ebolowa"), ("East", "Bertoua")], "Learn the regions and capitals in pairs.", points=2), True))
b = add(LM, P("Read: French Cameroun became independent on 1 January 1960. On 11 February 1961 the people of the British Cameroons voted: Northern Cameroons chose to join Nigeria and Southern Cameroons chose to join Cameroon. The union took place on 1 October 1961.",
              [PM("In which year did French Cameroun become independent?", "1960", ["1884", "1916", "1972"], "1960.", points=1),
               PM("What is the name of the vote of the people?", "plebiscite", ["census", "parade", "journey"], "A plebiscite is a vote.", points=1),
               PM("Which part chose to join Nigeria?", "Northern Cameroons", ["Southern Cameroons", "Littoral", "French Cameroun"], "Northern Cameroons voted for Nigeria.", points=1),
               PN("How many years are there between 1960 and 1972?", 12, "1972 − 1960 = 12.", points=2)]), True)
c1 = add(LM, M("application", "Which is a duty of a pupil?", "to obey the school rules", ["to break desks", "to come late", "to shout in class"], "Obeying rules is a duty."), True)
c2 = add(LM, M("application", "What does a red traffic light mean?", "stop", ["go", "turn left", "park"], "Red means stop."), True)
c3 = add(LM, O("Give THREE rules to cross the road safely.", "1. Stop at the edge of the pavement. 2. Look left, right and left again. 3. Cross at a zebra crossing and walk, do not run.", "1 mark for each correct rule (stop at the edge, look both ways, use a safe crossing, do not run, hold a young child's hand).", points=3), True)
d1 = add(LM, N("application", "A map has the scale 1 cm to 20 km. Two towns are 4.5 cm apart. How far apart are they in km?", 90, "4.5 × 20 = 90 km.", unit="km", points=2), True)
d2 = add(LM, M("application", "On which continent is Cameroon?", "Africa", ["Asia", "Europe", "Oceania"], "Cameroon is in Central Africa."), True)
d3 = add(LM, M("application", "In a grid reference we write...", "the letter first, then the number", ["the number first, then the letter", "only letters", "only numbers"], "For example B2."), True)
p.mock("1", "FSLC mock paper — Social Studies", 60,
       "Answer ALL the questions. Total: 20 marks. Section A: geography (6 marks); Section B: history (5 marks); Section C: civic education (5 marks); Section D: Africa and maps (4 marks). This is an original practice paper: its format is to be checked against the official texts.",
       [("Section A — Geography of Cameroon (6 marks)", a), ("Section B — History (5 marks)", [b]), ("Section C — Civic education (5 marks)", [c1, c2, c3]), ("Section D — Africa and maps (4 marks)", [d1, d2, d3])])
p.write()
